#!/usr/bin/env bash
# Format-and-confidence warm-up SFT for Llama-3.1-8B-Instruct.
#
# Input data must be generated by:
#   examples/data_preprocess/build_correct_sft_warmup.py
# The final checkpoint also saves a HuggingFace copy under:
#   ${SAVE_DIR}/global_step_<N>/huggingface

set -euo pipefail
set -x

export WANDB_API_KEY="Your Wandb API Key"
export WANDB_MODE="online"
export ACCELERATE_LOG_LEVEL=info
export HYDRA_FULL_ERROR=1

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
PYTHON_BIN="${PYTHON_BIN:-PYTHON_ENV}"

NPROC_PER_NODE="${NPROC_PER_NODE:-4}"

MODEL_PATH="${MODEL_PATH:-PATH_TO_Qwen3-8B}"
TRAIN_DATA="${TRAIN_DATA:-data/sft/qwen38b_dapo17k_sft_warmup/train.parquet}"
VAL_DATA="${VAL_DATA:-data/sft/qwen38b_dapo17k_sft_warmup/val.parquet}"

EXP_NAME="${EXP_NAME:-SFT_Qwen3-8B_DAPO17k_Correct2K}"

PROJECT_NAME="${PROJECT_NAME:-Calibration}"
SAVE_DIR="${SAVE_DIR:-${REPO_ROOT}/checkpoints/${PROJECT_NAME}/${EXP_NAME}}"

# This is the global batch size across all GPUs.  With the default four GPUs,
# each rank receives 8 examples and accumulates four micro-batches of size 2.
TRAIN_BATCH_SIZE="${TRAIN_BATCH_SIZE:-32}"
MICRO_BATCH_SIZE_PER_GPU="${MICRO_BATCH_SIZE_PER_GPU:-2}"
# The generated 2k warm-up set currently has a 4270-token maximum under the
# Llama tokenizer.  5120 avoids dropping its final boxed-answer/confidence.
MAX_LENGTH="${MAX_LENGTH:-5120}"
LR="${LR:-1e-5}"
TOTAL_EPOCHS="${TOTAL_EPOCHS:-1}"
SAVE_FREQ="${SAVE_FREQ:-50}"
TEST_FREQ="${TEST_FREQ:-50}"
SEED="${SEED:-42}"


cd "${REPO_ROOT}"

"${PYTHON_BIN}" -m torch.distributed.run --standalone --nnodes=1 --nproc_per_node="${NPROC_PER_NODE}" \
    -m verl.trainer.fsdp_sft_trainer \
    data.train_files="${TRAIN_DATA}" \
    data.val_files="${VAL_DATA}" \
    data.multiturn.enable=true \
    data.multiturn.messages_key=messages \
    data.multiturn.enable_thinking_key=enable_thinking \
    data.train_batch_size="${TRAIN_BATCH_SIZE}" \
    data.micro_batch_size_per_gpu="${MICRO_BATCH_SIZE_PER_GPU}" \
    data.max_length="${MAX_LENGTH}" \
    data.truncation=error \
    model.partial_pretrain="${MODEL_PATH}" \
    model.trust_remote_code=true \
    model.enable_gradient_checkpointing=true \
    model.fsdp_config.model_dtype=bfloat16 \
    model.lora_rank=0 \
    optim.lr="${LR}" \
    optim.lr_warmup_steps_ratio=0.1 \
    optim.lr_scheduler=cosine \
    optim.clip_grad=1.0 \
    trainer.default_local_dir="${SAVE_DIR}" \
    trainer.project_name="${PROJECT_NAME}" \
    trainer.experiment_name="${EXP_NAME}" \
    trainer.total_epochs="${TOTAL_EPOCHS}" \
    trainer.save_freq="${SAVE_FREQ}" \
    trainer.test_freq="${TEST_FREQ}" \
    trainer.logger="['console','wandb']" \
    trainer.seed="${SEED}" \
    trainer.resume_mode=disable \
    trainer.checkpoint.save_contents="['model','optimizer','extra','hf_model']" \
    "$@"
